#[utoipa::path(
    get,
    path = "/account/billing/transactions",
    tag = "auth",
    params(
        ("limit" = Option<i64>, Query, description = "Maximum number of transactions to return (default 50, max 200)"),
        ("offset" = Option<i64>, Query, description = "Offset for pagination (default 0)"),
    ),
    responses(
        (status = 200, description = "List of transactions", body = TransactionsListResponse),
        (status = 404, description = "Account not found", body = ErrorBody),
    ),
    security(("api_key" = []))
)]
pub(crate) async fn list_transactions(
    State(state): State<Arc<AuthState>>,
    Extension(user): Extension<AuthenticatedUser>,
    axum::extract::Query(params): axum::extract::Query<std::collections::HashMap<String, String>>,
) -> Result<Json<TransactionsListResponse>, ApiError> {
    let account_id = get_user_account_id(&state.pool, user.user_id, user.selected_account_id)
        .await
        .map_err(|_| err(StatusCode::NOT_FOUND, "Account not found", "not_found"))?;

    let limit: i64 = params
        .get("limit")
        .and_then(|v| v.parse().ok())
        .unwrap_or(50)
        .min(200);
    let offset: i64 = params
        .get("offset")
        .and_then(|v| v.parse().ok())
        .unwrap_or(0);

    let total: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM transactions WHERE account_id = $1")
        .bind(account_id)
        .fetch_one(&state.pool)
        .await
        .map_err(|_| {
            err(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Database error",
                "internal_error",
            )
        })?;

    let rows = sqlx::query(
        "SELECT id, type, amount, balance_after, description, created_at \
         FROM transactions WHERE account_id = $1 \
         ORDER BY created_at DESC LIMIT $2 OFFSET $3",
    )
    .bind(account_id)
    .bind(limit)
    .bind(offset)
    .fetch_all(&state.pool)
    .await
    .map_err(|_| {
        err(
            StatusCode::INTERNAL_SERVER_ERROR,
            "Database error",
            "internal_error",
        )
    })?;

    let transactions: Vec<TransactionResponse> = rows
        .iter()
        .map(|r| TransactionResponse {
            id: r.get::<uuid::Uuid, _>("id").to_string(),
            tx_type: r.get("type"),
            amount: r.get("amount"),
            balance_after: r.get("balance_after"),
            description: r.get("description"),
            created_at: r
                .get::<chrono::DateTime<chrono::Utc>, _>("created_at")
                .to_rfc3339(),
        })
        .collect();

    Ok(Json(TransactionsListResponse {
        transactions,
        total,
    }))
}

//! Volume-based tiered pricing.

/// Calculate the price in cents for a given number of credits.
/// Volume-based: the entire quantity is priced at the tier rate.
///
/// | Volume      | Per credit | Per 1K |
/// |-------------|-----------|--------|
/// | 1–999       | $0.010    | $10    |
/// | 1,000–4,999 | $0.008    | $8     |
/// | 5,000–9,999 | $0.007    | $7     |
/// | 10,000+     | $0.005    | $5     |
pub fn calculate_price_cents(credits: i64) -> i64 {
    // Unit price in tenths of a cent to avoid floating point
    let rate_tenths = if credits >= 10_000 {
        5 // $0.005 = 0.5 cents
    } else if credits >= 5_000 {
        7 // $0.007 = 0.7 cents
    } else if credits >= 1_000 {
        8 // $0.008 = 0.8 cents
    } else {
        10 // $0.010 = 1.0 cent
    };
    // cents = credits * rate_tenths / 10, ceiling
    (credits * rate_tenths + 9) / 10
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_price_small_volume() {
        // 100 credits at $0.01 each = $1.00 = 100 cents
        assert_eq!(calculate_price_cents(100), 100);
    }

    #[test]
    fn test_price_mid_volume() {
        // 1000 credits at $0.008 each = $8.00 = 800 cents
        assert_eq!(calculate_price_cents(1000), 800);
    }

    #[test]
    fn test_price_high_volume() {
        // 10000 credits at $0.005 each = $50.00 = 5000 cents
        assert_eq!(calculate_price_cents(10000), 5000);
    }
}

